def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for v in row:
            counts[v] = counts.get(v, 0) + 1
    bg = max(counts, key=counts.get)
    fg = next(v for v in counts if v != bg)

    points = [(r, c) for r in range(h) for c in range(w)
              if grid[r][c] == fg]
    if not points:
        return [row[:] for row in grid]

    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)

    out = [row[:] for row in grid]

    # Complete the outer rectangular boundary.
    for c in range(c0, c1 + 1):
        if grid[r0][c] == bg:
            out[r0][c] = 2
        if grid[r1][c] == bg:
            out[r1][c] = 2
    for r in range(r0, r1 + 1):
        if grid[r][c0] == bg:
            out[r][c0] = 2
        if grid[r][c1] == bg:
            out[r][c1] = 2

    # Complete supported internal vertical strokes that span the boundary rows.
    for c in range(c0 + 1, c1):
        if (grid[r0][c] == fg and grid[r1][c] == fg and
                any(grid[r][c] == fg for r in range(r0 + 1, r1))):
            for r in range(r0, r1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2

    return out
